const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',open);toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');toggle.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰'}));
document.querySelectorAll('.service-list details').forEach(detail=>detail.addEventListener('toggle',()=>{detail.querySelector('b').textContent=detail.open?'−':'+';if(detail.open)document.querySelectorAll('.service-list details').forEach(other=>{if(other!==detail)other.open=false})}));
function showDialog(id){document.getElementById(id).showModal();document.body.classList.add('modal-open')}document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.classList.remove('modal-open'));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();showDialog('contact-dialog')}));
document.getElementById('brief-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const brief=`LUMIOR STUDIO — PROJECT BRIEF\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nService: ${f.get('service')}\n\nProject:\n${f.get('message')}\n\nCreated: ${new Date().toLocaleDateString()}\n`;const url=URL.createObjectURL(new Blob([brief],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='lumior-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('form-status').textContent='Your brief is ready. Saved to your downloads — no details have been sent.'});
const projects={bloom:{title:'Bloom Botanicals',info:'An illustrative brand and e-commerce concept for a botanical wellbeing label. Soft editorial typography, natural colours and a considered shopping experience turn a simple product range into a memorable world. Scope: visual identity, art direction, responsive storefront and conversion design.'},forma:{title:'Forma Living',info:'An illustrative digital direction for a contemporary interiors brand. Sculptural forms, warm neutrals and spacious layouts give the products room to speak. Scope: digital strategy, website design, product storytelling and a foundation for paid campaigns.'}};document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const p=projects[b.dataset.project];document.getElementById('project-title').textContent=p.title;document.getElementById('project-info').textContent=p.info;showDialog('project-dialog')}));document.getElementById('project-cta').addEventListener('click',()=>document.getElementById('project-dialog').close());
const quotes=[['“Make it beautiful. Make it useful. Make it mean something. The best digital experiences do all three.”','Craft, with purpose.'],['“Your website, your search strategy and your ads should be having the same conversation. We bring them together.”','One connected picture.'],['“Stay curious. Listen closely. Keep making things better. That’s how a good partnership becomes great work.”','People before processes.']];let quoteIndex=0;function changeQuote(dir){quoteIndex=(quoteIndex+dir+quotes.length)%quotes.length;document.getElementById('quote-text').textContent=quotes[quoteIndex][0];document.getElementById('quote-name').textContent=quotes[quoteIndex][1];document.getElementById('quote-count').textContent=`0${quoteIndex+1} — 03`;}document.getElementById('prev-quote').addEventListener('click',()=>changeQuote(-1));document.getElementById('next-quote').addEventListener('click',()=>changeQuote(1));
document.querySelectorAll('[data-legal]').forEach(b=>b.addEventListener('click',()=>{const privacy=b.dataset.legal==='privacy';document.getElementById('legal-title').textContent=privacy?'Your privacy matters.':'A lighter footprint.';document.getElementById('legal-content').textContent=privacy?'This demonstration website does not send form information to a server. Project briefs are generated locally in your browser and downloaded only when you choose. The website uses Google Fonts, which makes a request to Google to load the typeface. No analytics or advertising trackers have been added.':'This website does not set analytics, marketing or preference cookies. There are no optional cookies to enable. Your project form stays in the current browser tab until you close or refresh the page.';showDialog('legal-dialog')}));document.getElementById('year').textContent=new Date().getFullYear();
